function getProfileHabitsAnswer(enabled, question = "") {
  if (!enabled) return "";
  const q = String(question || "").normalize("NFKC").toLowerCase();
  const asksHabits = /आदत|आदतें|आदतों|रोजमर्रा|दैनिक व्यवहार|habits?|aadat|aadatein|aadaton|meri aadat|meri aadatein/i.test(q);
  return asksHabits ? PROFILE_HABITS_ANSWER : "";
}

